"""Explain hash bucket sizes, init mutex and packed pool handles."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1893': ('0번부터 7번까지 서랍은 모두 여덟 개예요. 마지막 번호와 전체 개수는 하나 차이가 나요.', '해시 표의 개수·마스크와 빈 원형 목록을 이해합니다.', '0~7번 서랍 여덟 개와 각 서랍의 자기 자신으로 돌아오는 next·prev 화살표를 그리세요.', ['stack depot은 호출 경로를 검색하기 위해 해시 표를 사용해요. 해시는 자료를 작은 값으로 요약하는 방법이고 bucket은 같은 검색 후보들이 모인 칸이에요. 각 칸에는 기록 목록의 머리인 list_head가 있어요.', 'init_stack_table은 칸 수 entries만큼 반복하며 모든 머리에 INIT_LIST_HEAD를 적용해요. 이 함수는 next와 prev를 머리 자신으로 연결해요. next는 다음, prev는 이전 항목을 가리키는 포인터예요.', '이렇게 자기 자신으로 돌아오는 원형 목록에서는 머리 다음이 바로 머리이면 기록이 없는 빈 목록이에요. 빈 목록이라고 next·prev가 반드시 NULL이어야 하는 것은 아니에요. 목록 구현마다 빈 상태 표현이 달라요.', '이른 초기화에서 할당기가 크기를 자동 계산했다면 stack_hash_mask + 1로 실제 칸 수를 얻어요. mask가 4095이면 칸 번호가 0~4095이므로 총 4096칸이에요. 최대 번호를 개수로 착각하면 마지막 칸을 빠뜨려요.', '칸 수 N이 2의 거듭제곱일 때 mask=N-1로 두고 hash & mask로 칸 번호를 구할 수 있어요. &는 각 이진수 자리에서 둘 다 1인 자리만 남기는 연산이에요. 여덟 칸이면 mask 7이 아래 세 자리를 남겨 0~7 중 하나를 만들어요.', '예를 들어 hash 13은 이진수 1101이고 mask 7은 0111이에요. 두 값의 & 결과는 0101, 즉 5예요. 이 계산은 검색할 칸을 정하는 것이지 실제 기록이 일치한다고 판정하는 마지막 비교는 아니에요.'], [('mask가 4095이면 표의 칸 수는 얼마인가요?', ['4095칸이에요', '4096칸이에요'], '정답은 두 번째예요. 0번도 한 칸이므로 0~4095는 4096개예요. 개수는 mask+1로 구해요.'), ('INIT_LIST_HEAD로 만든 빈 목록의 연결은 어떤 모양인가요?', ['next와 prev가 머리 자신을 가리켜요', 'next와 prev가 언제나 NULL이에요'], '정답은 첫 번째예요. Linux의 이 목록은 원형 연결을 사용해요. 머리로 바로 돌아오는 모양이 빈 목록을 나타내요.')]), 'os1894': ('이미 설치된 보관함을 다시 만들 필요는 없어요. 준비 담당자는 잠금을 잡고 상태를 확인한 뒤, 성공하든 실패하든 잡은 잠금을 풀고 나가요.', '늦은 초기화의 중복 방지와 공통 잠금 해제 경로를 이해합니다.', '잠금→상태 확인→필요하면 할당→공통 잠금 해제→결과 반환을 그리세요.', ['stack_depot_init은 부팅 뒤에도 사용할 수 있는 저장소 초기화 함수예요. 먼저 mutex를 잡아요. mutex는 여러 실행이 같은 준비 작업을 동시에 진행하지 않도록 한 번에 하나씩 들여보내는 잠금이에요.', '잠금 안에서 stack_depot_disabled 또는 stack_table을 확인해요. 저장소가 비활성이거나 표가 이미 있으면 out_unlock이라는 공통 끝부분으로 가요. 새 표를 항상 할당해 덮어쓰는 함수가 아니에요.', '준비가 필요하면 표의 칸 수를 계산하고 kvcalloc으로 list_head 배열 공간을 얻어요. 각 칸은 후보 기록의 목록 머리예요. 성공하면 mask를 칸 수 - 1로 정하고 모든 머리를 빈 원형 목록으로 초기화해요.', '공간을 얻지 못하면 stack_depot_disabled를 true로 바꾸고 결과 ret에 -ENOMEM을 넣어요. ENOMEM은 메모리를 얻지 못했다는 오류예요. 이후 goto out_unlock으로 같은 끝부분에 가요.', 'out_unlock에서는 mutex_unlock을 한 뒤 ret를 반환해요. 이미 준비된 경우, 비활성인 경우, 할당 실패, 성공 경로가 모두 이 잠금 해제 지점을 거쳐요. 실패했다고 잠금을 계속 잡아 두면 다음 호출이 진행하지 못할 수 있어요.', '초기 ret는 0이므로 이미 표가 있거나 비활성이라 생략한 경우에도 0이 나올 수 있어요. 0 반환이 이번 호출에서 새 표를 만들었다는 뜻은 아니에요. 실제 동시 실행 검증과 이 코드의 경로 읽기는 구별해서 봐요.'], [('표가 이미 있으면 이 함수는 새 표를 다시 만들어 덮어쓰나요?', ['네. 호출할 때마다 무조건 다시 만들어요', '아니요. 공통 잠금 해제 경로로 가요'], '정답은 두 번째예요. stack_table이 있으면 out_unlock으로 이동해요. 같은 준비를 중복해서 할 필요가 없기 때문이에요.'), ('할당 실패로 오류를 반환할 때도 mutex를 푸나요?', ['네. out_unlock에서 풀고 반환해요', '아니요. 실패하면 잠금을 그대로 남겨요'], '정답은 첫 번째예요. 실패 분기도 공통 끝부분으로 가요. 오류 코드와 잠금 정리 순서를 함께 확인하세요.')]), 'os1895': ('메모리 페이지의 개수가 같아도 한 페이지가 더 크면 전체 메모리 양은 더 많아요. 검색 표 크기는 개수와 크기를 함께 보고 정해요.', '페이지 규모에서 bucket 수를 계산하고 최소·최대 제한을 적용합니다.', '16384페이지에 PAGE_SHIFT 16을 적용해 16384×4=65536칸을 계산하세요.', ['표 크기 단계 stack_bucket_number_order가 이미 정해졌다면 칸 수는 1을 그 단계만큼 왼쪽 이동해 구해요. 이는 2의 단계승이에요. order 20은 20칸이 아니라 2를 스무 번 곱한 1048576칸이에요.', '단계가 정해지지 않았으면 nr_free_buffer_pages로 페이지 수를 얻고 roundup_pow_of_two로 그 수 이상인 가장 작은 2의 거듭제곱으로 올려요. 예를 들어 5는 8, 이미 8이면 8이에요.', '다음에는 PAGE_SHIFT와 scale 14를 비교해요. PAGE_SHIFT는 페이지 바이트 크기가 2의 몇 승인지 나타내요. 12면 4096바이트, 16이면 65536바이트예요. 같은 페이지 수라도 실제 바이트 양이 달라요.', 'PAGE_SHIFT 16은 scale 14보다 2 커요. 따라서 왼쪽으로 2칸 이동해 4배로 만들어요. 16384페이지는 이미 2의 거듭제곱이라 그대로이고, 16384×4=65536칸이 돼요. 반대로 PAGE_SHIFT 12이면 오른쪽 2칸 이동해 4로 나눠요.', '마지막으로 최소 2의 12승인 4096칸, 최대 2의 20승인 1048576칸 범위에 맞춰요. 계산 결과가 1024이면 4096으로 올리고 최대를 넘으면 1048576으로 제한해요.', '이전 이른 초기화에서 KASAN 때문에 최대 단계가 정해질 수 있어요. 많은 서로 다른 호출 경로가 생기는 사용을 고려한 선택이에요. 이 수업 숫자는 유효한 페이지 수를 넣은 계산 예시이며 실제 메모리를 할당하거나 모든 컴퓨터 설정을 시험한 것은 아니에요.'], [('자동 크기 계산에서 16384페이지, PAGE_SHIFT 16이면 bucket 수는 얼마인가요?', ['페이지 크기와 상관없이 항상 4096개예요', '16384를 4배 한 65536개예요'], '정답은 두 번째예요. 16-14=2이므로 왼쪽 2칸 이동, 즉 4배예요. 이 결과는 최소·최대 범위 안이라 그대로 사용해요.'), ('최대 bucket order가 20이면 몇 칸인가요?', ['2의 20승인 1048576칸이에요', '20칸이에요'], '정답은 첫 번째예요. order는 칸 수 자체가 아니라 2의 거듭제곱 단계예요. 둘을 혼동하면 표 크기를 매우 작게 계산하게 돼요.')]), 'os1896': ('보관함 번호와 그 안의 위치를 작은 쪽지 하나에 담아요. 쪽지 번호 0을 없음 표시로 남기려면 첫 보관함은 1로 적는 약속이 필요해요.', '압축 기록 번호의 pool 번호·위치와 표현 범위를 이해합니다.', '실제 pool 0·위치 0을 기록할 때 pool_index_plus_1은 1이라고 적으세요. 위치 32바이트는 16바이트 단위로 2예요.', ['stack depot은 기록들을 pool이라는 큰 메모리 공간 안에 담아요. stack_pools 배열은 각 pool의 주소를 가리켜요. handle은 어떤 pool의 어느 위치에 기록이 있는지 나타내는 작은 식별 번호예요.', '헤더는 handle을 32비트 정수로 정의하고 pool_index_plus_1, offset, extra 부분으로 나누어요. 비트는 0 또는 1을 담는 자리이고 bitfield는 정수 안에 몇 자리씩 나누어 항목을 담는 C 표현이에요.', '실제 pool 번호에 1을 더해 pool_index_plus_1에 넣어요. 첫 pool의 실제 번호가 0이어도 기록 번호의 이 부분은 1이에요. 첫 pool 첫 기록까지 0 handle이 되는 일을 피하려는 규칙이에요. 0은 기록 없음이나 실패를 나타낼 때 쓰여요.', 'offset에는 바이트 위치를 16바이트 단위로 줄여 저장해요. DEPOT_STACK_ALIGN이 4라 pool_offset을 오른쪽으로 4칸 이동해요. 정렬된 위치 32바이트는 32/16=2로 표현할 수 있어요. 앞에서 pool 번호에 1을 더한 것은 데이터를 1바이트 옮기는 일이 아니에요.', 'extra에는 사용자가 덧붙일 정보를 담을 수 있고 새 기록 번호를 준비할 때는 0으로 설정해요. 이렇게 저장 위치와 작은 추가 정보를 같은 번호에 담지만 실제 호출 경로 주소 배열 전체를 그 번호에 복사하는 것은 아니에요.', 'bitfield의 실제 비트 배치는 컴파일러와 기종의 규약을 따라요. ABI는 컴파일된 코드와 자료 배치가 서로 맞도록 정한 약속이에요. 한 64비트 리틀엔디언 환경에서 관찰한 숫자가 모든 환경에서 같은 배치를 보장하지는 않아요. 리틀엔디언은 여러 바이트 값을 낮은 바이트부터 저장하는 방식이에요.'], [('pool 번호에 1을 더해 저장하는 이유는 무엇인가요?', ['실제 데이터를 1바이트 뒤로 옮기려고요', '첫 기록을 없음·실패 표시인 0 handle과 구별하려고요'], '정답은 두 번째예요. 바꾸는 것은 식별 번호의 pool 부분이에요. 실제 데이터 위치를 한 바이트 밀어내는 작업과 달라요.'), ('한 64비트 리틀엔디언 환경의 bitfield 실험만으로 모든 기종의 배치를 보장하나요?', ['아니요. 실험한 환경과 자료 배치 규약의 범위를 따라요', '네. C bitfield는 모든 환경에서 같은 위치에 놓여요'], '정답은 첫 번째예요. 각 부분에 담는 의미와 실제 정수의 비트 배치는 나누어 봐야 해요. 한 환경의 숫자 예를 모든 ABI의 보장으로 넓히지 마세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_469.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
